#!/usr/bin/env python3
"""One-shot materializer for the Araucaria organic terrain pass."""

import base64
from pathlib import Path

FILES = {
    "build/generated/araucaria/tiles.png": "",
    "build/generated/araucaria/metatiles.bin": "",
    "build/generated/araucaria/metatile_attributes.bin": "",
    "build/generated/araucaria/map.bin": "",
}

for path, encoded in FILES.items():
    target = Path(path)
    target.parent.mkdir(parents=True, exist_ok=True)
    target.write_bytes(base64.b64decode(encoded))
